/**
 * What the server half renders the button fixture to with the label "Press". The server test
 * holds the server half to it and the browser test hydrates it, so the two halves, which run on
 * two builds of Lit, are held to the same markup.
 */
export const BUTTON_MARKUP =
  '<!--lit-part 8icj+h3nvZI=--><!--lit-node 0--><button type="button" >\n    <!--lit-part-->Press<!--/lit-part-->\n  </button><!--/lit-part-->';
